CREATE TABLE public.care_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), elderly_name text NOT NULL, age integer NOT NULL, passcode text NOT NULL UNIQUE, allergies text[] NOT NULL DEFAULT '{}', conditions text[] NOT NULL DEFAULT '{}', caretaker_emails text[] NOT NULL DEFAULT '{}', is_demo boolean NOT NULL DEFAULT false);
GRANT ALL ON public.care_profiles TO service_role;
ALTER TABLE public.care_profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.medications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES public.care_profiles(id) ON DELETE CASCADE, name text NOT NULL, dosage text NOT NULL, frequency text NOT NULL DEFAULT 'Daily', time_of_day text NOT NULL DEFAULT 'Morning', scheduled_time text NOT NULL, instructions text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'upcoming', taken_at timestamptz);
GRANT ALL ON public.medications TO service_role;
ALTER TABLE public.medications ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES public.care_profiles(id) ON DELETE CASCADE, doctor_name text NOT NULL, specialty text NOT NULL, date_time timestamptz NOT NULL, location text NOT NULL, notes text NOT NULL DEFAULT '');
GRANT ALL ON public.appointments TO service_role;
ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.alert_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES public.care_profiles(id) ON DELETE CASCADE, alert_type text NOT NULL, recipient_email text NOT NULL, subject text NOT NULL, message_body text NOT NULL, sent_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.alert_logs TO service_role;
ALTER TABLE public.alert_logs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.care_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES public.care_profiles(id) ON DELETE CASCADE, token text NOT NULL UNIQUE, role text NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '8 hours');
GRANT ALL ON public.care_sessions TO service_role;
ALTER TABLE public.care_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.care_pin_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempted_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.care_pin_attempts TO service_role;
ALTER TABLE public.care_pin_attempts ENABLE ROW LEVEL SECURITY;
